parameters.jsCode:
const input = $input.first().json;
const params = input.params || input;
const cstTime = new Date().toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' });

return {
  username: params.username || '',
  display_name: params.display_name || '',
  ou: params.ou || 'OU=Users,DC=corp,DC=local',
  email: params.email || '',
  phone: params.phone || '',
  triggered_by: input.triggered_by || 'zops_api',
  timestamp: cstTime,
};

